_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Landing_page_views from Maplemonk.Custom_Facebook_Marketing_Beastlife_hourly_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'landing_page_view\' group by ad_id,date_start,hour having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fe ON Fb.ad_id = Fe.ad_id and Fb.date_start=Fe.date_start and fb.hour = fe.hour left join ( select ad_id ,date_start ,hour ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Initiate_checkouts from Maplemonk.Custom_Facebook_Marketing_Beastlife_hourly_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start,hour having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Ff ON Fb.ad_id = Ff.ad_id and Fb.date_start=Ff.date_start and fb.hour = ff.hour left join ( select ad_id ,date_start ,hour ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Initiate_checkouts_Value from Maplemonk.Custom_Facebook_Marketing_Beastlife_hourly_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start,hour having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Ffv ON Fb.ad_id = Ffv.ad_id and Fb.date_start=Ffv.date_start and fb.hour = ffv.hour left join ( select ad_id ,date_start ,hour ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.1d_click\') as FLOAT64)) one_day_click_conversions from Maplemonk.Custom_Facebook_Marketing_Beastlife_hourly_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id,date_start,hour having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.1d_click\') as FLOAT64)) is not null )Fg ON Fb.ad_id = Fg.ad_id and Fb.date_start=Fg.date_start and fb.hour = fg.hour left join ( select ad_id ,ad_name ,date_start ,hour ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.1d_click\') as FLOAT64)) one_day_click_conversion_value from Maplemonk.Custom_Facebook_Marketing_Beastlife_hourly_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start ,hour having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.1d_click\') as FLOAT64)) is not null )Fgv ON Fb.ad_id = Fgv.ad_id and Fb.date_start=Fgv.date_start and fb.hour = fgv.hour group by Adset_Name, Adset_ID,fb.ad_id,fb.AD_NAME, Account_Name, Account_ID, Campaign_Name, Campaign_ID,Fb.date_start, fb.hour ;",
